CREATE VIEW v_digital AS
  SELECT gno, gname, category, price, stock
  FROM goods WHERE category = '数码'
  WITH CHECK OPTION;
CREATE VIEW v_sales(gno, gname, total) AS
  SELECT g.gno, g.gname, SUM(o.qty)
  FROM goods g JOIN orders o ON g.gno = o.gno
  GROUP BY g.gno, g.gname;
UPDATE v_digital SET stock = 30
  WHERE gno = 'G01';
SELECT * FROM v_sales WHERE total >= 5;
CREATE INDEX idx_odate ON orders(odate);
CREATE UNIQUE INDEX uk_gname ON goods(gname);
SHOW INDEX FROM orders;
